"""Crop / disease vocabulary (generated by scripts/build_catalogue.py)."""
import json
import re
from functools import lru_cache
from pathlib import Path

PATH = Path(__file__).resolve().parents[1] / "data" / "catalogue.json"
UNASSESSED = "Not assessed by AI"      # stored as the disease when the AI does not cover the crop
_clean = re.compile(r"[^a-z0-9]")


def _key(text: str) -> str:
    return _clean.sub("", text.lower())


@lru_cache(maxsize=1)
def load() -> dict:
    data = json.loads(PATH.read_text())
    by_key = {}
    for c in data["crops"]:
        for a in c["aliases"] + [c["id"], c["name"]]:
            by_key[_key(a)] = c
    return {"crops": data["crops"], "by_key": by_key}


def crops() -> list[dict]:
    return load()["crops"]


def get_crop(text: str | None) -> dict | None:
    return load()["by_key"].get(_key(text)) if text and text.strip() else None


def canonical_crop_name(text: str) -> str:
    """Expert-typed crop -> catalogue name when it matches, otherwise the typed text (trimmed)."""
    c = get_crop(text)
    return c["name"] if c else text.strip()


def canonical_disease_name(crop_text: str | None, disease_text: str) -> str:
    """Match ignoring case/punctuation against the crop's known diseases; otherwise keep what the expert typed."""
    typed = disease_text.strip()
    crop = get_crop(crop_text)
    pools = [crop["diseases"]] if crop else [c["diseases"] for c in crops()]
    for pool in pools:
        for d in pool:
            if _key(d) == _key(typed):
                return d
    return typed
